import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { after, before, describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { COMPONENTS } from '../lib/components.mjs';
import { plan, requirePublicationEnabled } from '../release.mjs';
import {
  SYNTHETIC_REPOSITORY,
  git,
  gitEnvironment,
  monorepoHistory,
  synthetic,
} from './support/repository.mjs';

const RUNNER = fileURLToPath(new URL('./support/run-release.mjs', import.meta.url));
const PUBLIC = `https://github.com/${SYNTHETIC_REPOSITORY}`;

const WORKSPACE = {
  'Substitute/Cargo.toml':
    '[workspace]\nmembers = ["crates/app"]\nexclude = ["third_party/wry"]\n\n' +
    '[workspace.package]\nversion = "0.1.0"\nedition = "2024"\n\n[workspace.dependencies]\nserde = "=1.0.0"\n',
  'Substitute/crates/app/Cargo.toml': '[package]\nname = "app"\nversion.workspace = true\n',
  'Substitute/Cargo.lock':
    '# This file is automatically @generated by Cargo.\nversion = 4\n\n' +
    '[[package]]\nname = "app"\nversion = "0.1.0"\ndependencies = [\n "serde",\n "wry",\n]\n\n' +
    '[[package]]\nname = "serde"\nversion = "1.0.0"\nsource = "registry+https://github.com/rust-lang/crates.io-index"\n\n' +
    '[[package]]\nname = "wry"\nversion = "0.1.0"\n',
};

/**
 * Run one component's production semantic-release against the repository itself, with no
 * remote, in a separate process. With `record`, GitHub publication writes what it received there.
 */
function run(root, component, settings) {
  const { dryRun = true, record, baseline = null, env = {} } = settings;
  const request = join(root, '..', `${component}-request.json`);
  writeFileSync(
    request,
    JSON.stringify({ root, component, dryRun, record, baseline, env, publicRepositoryUrl: PUBLIC }),
    'utf8',
  );
  const result = spawnSync(process.execPath, [RUNNER, request], {
    env: gitEnvironment(),
    encoding: 'utf8',
    windowsHide: true,
    maxBuffer: 64 * 1024 * 1024,
  });
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout.trim().split('\n').at(-1));
}

/** Every ref and the work tree state, to prove a run left the repository as it was. */
function state(root) {
  return {
    refs: git(root, ['for-each-ref', '--format=%(refname) %(objectname)']),
    status: git(root, ['status', '--porcelain', '--untracked-files=all']),
    remotes: git(root, ['remote']),
  };
}

describe('per-component semantic-release', () => {
  let history;
  let root;
  let sugar;
  before(() => {
    history = monorepoHistory();
    root = history.repository.root;
    sugar = synthetic(COMPONENTS.sugarcubes, history.commits).baseline;
    history.repository.commit('build(substitute): declare the workspace version', WORKSPACE);
    git(root, ['tag', 'substitute-v0.1.0']);
    history.repository.commit('feat(panel): add a panel', { 'Sugar/frontend/panel.ts': 'x\n' });
  });
  after(() => history.repository.dispose());

  it('releases SugarCubes alone after a SugarCubes-only change, continuing its sequence', () => {
    const outcome = run(root, 'sugarcubes', { baseline: sugar });
    assert.equal(outcome.version, '0.16.0');
    assert.equal(outcome.tag, 'sugarcubes-v0.16.0');
    assert.equal(outcome.released, false);
    assert.match(outcome.notes, /add a panel/);
    assert.match(outcome.notes, /add a cube/);
    assert.match(outcome.notes, /keep cube names/);
    assert.doesNotMatch(outcome.notes, /keep the window|declare the workspace/);
    assert.deepEqual(run(root, 'substitute', {}), {
      released: false,
      version: '',
      tag: '',
      notes: '',
    });
  });

  it('dry-runs in a disposable clone, leaving the repository untouched even with credentials', () => {
    const before = state(root);
    const outcome = run(root, 'sugarcubes', {
      baseline: sugar,
      env: { CI: 'true', GITHUB_ACTIONS: 'true', GITHUB_TOKEN: 'not-a-token' },
    });
    assert.equal(outcome.version, '0.16.0');
    assert.deepEqual(state(root), before);
  });

  it('links notes to the public repository and lists breaking changes under their heading', () => {
    history.repository.commit(
      'feat(nodes)!: rename cube inputs\n\nBREAKING CHANGE: inputs renamed',
      {
        'Sugar/sugarcubes/inputs.py': 'INPUTS = {}\n',
      },
    );
    const { notes } = run(root, 'sugarcubes', { baseline: sugar });
    assert.match(notes, /### ⚠ BREAKING CHANGES\n\n\* \*\*nodes:\*\* inputs renamed/);
    assert.match(notes, /### Features\n/);
    assert.match(notes, /### Bug Fixes\n/);
    assert.ok(notes.includes(`(${PUBLIC}/compare/sugarcubes-v0.15.3...sugarcubes-v0.16.0)`));
    for (const [, link] of notes.matchAll(/\]\(([^)]+)\)/g)) {
      assert.ok(link.startsWith(`${PUBLIC}/`), link);
    }
  });

  it('bumps the patch version for a fix or perf change and the minor version for a breaking change', () => {
    history.repository.commit('fix(update): retry a failed check', {
      'Substitute/crates/app/src/main.rs': 'fn main() { retry() }\n',
    });
    assert.equal(run(root, 'substitute', {}).version, '0.1.1');
    history.repository.commit('perf(canvas): draw less', {
      'Substitute/crates/app/src/draw.rs': '\n',
    });
    assert.equal(run(root, 'substitute', {}).version, '0.1.1');
    history.repository.commit('feat(update)!: change the feed\n\nBREAKING CHANGE: new feed', {
      'Substitute/crates/app/src/feed.rs': '\n',
    });
    assert.equal(run(root, 'substitute', {}).version, '0.2.0');
  });

  it('writes the changelog and version files, commits them back and tags the release', () => {
    const before = git(root, ['rev-parse', 'HEAD']);
    const record = join(root, '..', 'published.json');
    const outcome = run(root, 'substitute', { dryRun: false, record });
    assert.equal(outcome.version, '0.2.0');
    assert.equal(outcome.released, true);
    const head = git(root, ['rev-parse', 'HEAD']);
    assert.notEqual(head, before);
    assert.equal(git(root, ['rev-list', '-n', '1', 'substitute-v0.2.0']), head);
    assert.equal(
      git(root, ['log', '-1', '--format=%s']),
      'chore(release): substitute 0.2.0 [skip ci]',
    );
    assert.deepEqual(git(root, ['show', '--name-only', '--format=', 'HEAD']).split('\n').sort(), [
      'Substitute/CHANGELOG.md',
      'Substitute/Cargo.lock',
      'Substitute/Cargo.toml',
    ]);
    const changelog = readFileSync(join(root, 'Substitute', 'CHANGELOG.md'), 'utf8');
    assert.match(changelog, /0\.2\.0/);
    assert.match(changelog, /retry a failed check/);
    assert.doesNotMatch(changelog, /add a panel|add a cube/);
    assert.match(
      readFileSync(join(root, 'Substitute', 'Cargo.toml'), 'utf8'),
      /\[workspace\.package\]\nversion = "0\.2\.0"/,
    );
    const lock = readFileSync(join(root, 'Substitute', 'Cargo.lock'), 'utf8');
    assert.match(lock, /name = "app"\nversion = "0\.2\.0"/);
    assert.match(lock, /name = "wry"\nversion = "0\.1\.0"/);
    assert.ok(existsSync(record));
    assert.equal(JSON.parse(readFileSync(record, 'utf8')).gitTag, 'substitute-v0.2.0');
    assert.equal(git(root, ['remote']), '');
    assert.equal(git(root, ['status', '--porcelain']), '');
  });

  it('finds nothing more to release for that component, and leaves the other one due', () => {
    assert.equal(run(root, 'substitute', {}).version, '');
    assert.equal(run(root, 'sugarcubes', { baseline: sugar }).version, '0.16.0');
  });
});

describe('a declared baseline without its tag', () => {
  let history;
  let root;
  let baseline;
  before(() => {
    history = monorepoHistory();
    root = history.repository.root;
    git(root, ['tag', '--delete', 'sugarcubes-v0.15.3']);
    const declared = history.repository.commit(
      'build(substitute): declare the workspace version',
      WORKSPACE,
    );
    baseline = { version: '0.1.0', commit: declared, versionFiles: ['Substitute/Cargo.toml'] };
    history.repository.commit('feat(update): offer updates', {
      'Substitute/crates/app/src/offer.rs': '\n',
    });
  });
  after(() => history.repository.dispose());

  it('plans and dry-runs from the declared release without creating its tag', async () => {
    const entry = { ...COMPONENTS.substitute, baseline };
    assert.deepEqual(
      (({ release, version, last }) => ({ release, version, last }))(await plan(root, entry)),
      { release: true, version: '0.2.0', last: '0.1.0' },
    );
    const before = state(root);
    const outcome = run(root, 'substitute', { baseline });
    assert.equal(outcome.version, '0.2.0');
    assert.match(outcome.notes, /offer updates/);
    assert.doesNotMatch(outcome.notes, /declare the workspace version|keep the window/);
    assert.deepEqual(state(root), before);
    assert.equal(git(root, ['tag', '--list', 'substitute-v*']), '');
  });

  it('tags the declared baseline in a real release, so the release continues it', () => {
    const record = join(root, '..', 'published.json');
    const outcome = run(root, 'substitute', { baseline, dryRun: false, record });
    assert.equal(outcome.version, '0.2.0');
    assert.equal(git(root, ['rev-list', '-n', '1', 'substitute-v0.1.0']), baseline.commit);
    assert.equal(
      git(root, ['rev-list', '-n', '1', 'substitute-v0.2.0']),
      git(root, ['rev-parse', 'HEAD']),
    );
  });
});

describe('publication switch', () => {
  it('refuses a real release outside the workflow or while RELEASES_ENABLED is not "true"', () => {
    assert.throws(() => requirePublicationEnabled({ RELEASES_ENABLED: 'true' }), /--dry-run/);
    assert.throws(() => requirePublicationEnabled({ GITHUB_ACTIONS: 'true' }), /RELEASES_ENABLED/);
    assert.throws(
      () => requirePublicationEnabled({ GITHUB_ACTIONS: 'true', RELEASES_ENABLED: 'TRUE' }),
      /RELEASES_ENABLED/,
    );
    requirePublicationEnabled({ GITHUB_ACTIONS: 'true', RELEASES_ENABLED: 'true' });
  });
});
